<?php
require_once __DIR__.'/includes/config.php';require_login();require_permission('debts');$uid=(int)$_SESSION['user_id'];$errors=[];
if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$saleId=filter_var($_POST['sale_id']??null,FILTER_VALIDATE_INT);$amount=filter_var($_POST['amount']??null,FILTER_VALIDATE_FLOAT);$note=trim($_POST['note']??'');if(!$saleId)$errors[]='Choose a valid sale.';if($amount===false||$amount<=0)$errors[]='Enter a repayment greater than zero.';if(!$errors){try{$pdo->beginTransaction();$q=$pdo->prepare('SELECT id,total,amount_paid FROM sales WHERE id=? AND user_id=? FOR UPDATE');$q->execute([$saleId,$uid]);$sale=$q->fetch();if(!$sale)throw new RuntimeException('Sale not found.');$balance=(float)$sale['total']-(float)$sale['amount_paid'];if($balance<=0)throw new RuntimeException('This sale has no outstanding balance.');if($amount>$balance+0.001)throw new RuntimeException('Repayment cannot exceed the outstanding balance of '.money($balance).'.');$q=$pdo->prepare('INSERT INTO debt_payments(user_id,sale_id,amount,note) VALUES(?,?,?,?)');$q->execute([$uid,$saleId,$amount,$note?:null]);$q=$pdo->prepare('UPDATE sales SET amount_paid=amount_paid+? WHERE id=? AND user_id=?');$q->execute([$amount,$saleId,$uid]);audit_log($pdo,'debt_repayment_recorded','sale',(int)$saleId,'Repayment '.number_format((float)$amount,2,'.','').' NGN');$pdo->commit();flash('Repayment recorded: '.money($amount));redirect('debts.php');}catch(Throwable $ex){if($pdo->inTransaction())$pdo->rollBack();$errors[]=$ex instanceof RuntimeException?$ex->getMessage():'Unable to record repayment. Please retry.';}}}
$q=$pdo->prepare('SELECT s.id,s.total,s.amount_paid,s.created_at,c.name customer,c.phone FROM sales s LEFT JOIN customers c ON c.id=s.customer_id WHERE s.user_id=? AND s.total>s.amount_paid ORDER BY s.created_at ASC');$q->execute([$uid]);$debts=$q->fetchAll();
$q=$pdo->prepare('SELECT dp.*,s.id sale_number,c.name customer FROM debt_payments dp JOIN sales s ON s.id=dp.sale_id LEFT JOIN customers c ON c.id=s.customer_id WHERE dp.user_id=? ORDER BY dp.id DESC LIMIT 100');$q->execute([$uid]);$payments=$q->fetchAll();$pageTitle='Customer debts';require __DIR__.'/includes/header.php';?>
<div class="page-heading"><div><h1 class="h3 fw-bold mb-1">Customer debts</h1><p class="muted mb-0">Record repayments and monitor outstanding credit sales.</p></div></div><?php foreach($errors as $err):?><div class="alert alert-danger"><?=e($err)?></div><?php endforeach;?>
<div class="card mb-4"><div class="card-body"><h2 class="h5 fw-bold mb-3">Outstanding balances</h2><div class="table-responsive"><table class="table align-middle"><thead><tr><th>Sale</th><th>Customer</th><th>Date</th><th>Total</th><th>Paid</th><th>Balance</th><th>Record repayment</th></tr></thead><tbody><?php foreach($debts as $d):$balance=(float)$d['total']-(float)$d['amount_paid'];?><tr><td><a href="receipt.php?id=<?=(int)$d['id']?>">#<?=(int)$d['id']?></a></td><td><?=e($d['customer']?:'Walk-in')?><div class="small text-secondary"><?=e($d['phone']??'')?></div></td><td><?=date('d M Y',strtotime($d['created_at']))?></td><td><?=money($d['total'])?></td><td><?=money($d['amount_paid'])?></td><td class="text-danger fw-semibold"><?=money($balance)?></td><td><form method="post" class="d-flex gap-2 flex-wrap"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><input type="hidden" name="sale_id" value="<?=(int)$d['id']?>"><input class="form-control form-control-sm" style="max-width:130px" type="number" name="amount" min="0.01" max="<?=e((string)$balance)?>" step="0.01" placeholder="₦ amount" required><input class="form-control form-control-sm" style="max-width:150px" name="note" maxlength="255" placeholder="Note (optional)"><button class="btn btn-sm btn-primary">Save</button></form></td></tr><?php endforeach;?></tbody></table><?php if(!$debts):?><div class="empty-state">No outstanding debts. Great work!</div><?php endif;?></div></div></div>
<div class="card"><div class="card-body"><h2 class="h5 fw-bold mb-3">Recent repayments</h2><div class="table-responsive"><table class="table"><thead><tr><th>Date</th><th>Sale</th><th>Customer</th><th>Amount</th><th>Note</th></tr></thead><tbody><?php foreach($payments as $p):?><tr><td><?=date('d M Y H:i',strtotime($p['paid_at']))?></td><td><a href="receipt.php?id=<?=(int)$p['sale_number']?>">#<?=(int)$p['sale_number']?></a></td><td><?=e($p['customer']?:'Walk-in')?></td><td class="text-success fw-semibold"><?=money($p['amount'])?></td><td><?=e($p['note']??'—')?></td></tr><?php endforeach;?></tbody></table><?php if(!$payments):?><div class="empty-state">No repayments recorded yet.</div><?php endif;?></div></div></div><?php require __DIR__.'/includes/footer.php';?>
